    v.sort_unstable();
    let (x, y, z) = (v[0], v[1], v[2]);

    // Parity invariant: each operation preserves the parity of (a+b+c),
    // so the final target T must satisfy (3T) % 2 == (a+b+c) % 2, i.e. T % 2 == sum % 2.
    let sum = x + y + z;
    let sum_par = sum & 1;

